CREATE EXTENSION IF NOT EXISTS "pgcrypto";

CREATE TABLE IF NOT EXISTS "ManufacturingPlant" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "tenantId" UUID NOT NULL, "workspaceId" UUID, "plantKey" TEXT NOT NULL, "name" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'active', "plantType" TEXT NOT NULL DEFAULT 'factory', "countryCode" TEXT, "region" TEXT, "timezone" TEXT, "address" JSONB NOT NULL DEFAULT '{}'::jsonb, "capabilities" JSONB NOT NULL DEFAULT '[]'::jsonb, "metadata" JSONB NOT NULL DEFAULT '{}'::jsonb, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "deletedAt" TIMESTAMP(3));
