CREATE INDEX IF NOT EXISTS "ManufacturingPlant_tenantId_workspaceId_idx" ON "ManufacturingPlant" ("tenantId", "workspaceId");
CREATE INDEX IF NOT EXISTS "ManufacturingPlant_tenantId_status_idx" ON "ManufacturingPlant" ("tenantId", "status");

CREATE TABLE IF NOT EXISTS "ProductionLine" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "tenantId" UUID NOT NULL, "workspaceId" UUID, "plantId" UUID, "lineKey" TEXT NOT NULL, "name" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'active', "lineType" TEXT NOT NULL DEFAULT 'assembly', "capacityPerHour" DECIMAL(18,4) NOT NULL DEFAULT 0, "shiftPattern" JSONB NOT NULL DEFAULT '{}'::jsonb, "constraints" JSONB NOT NULL DEFAULT '{}'::jsonb, "metadata" JSONB NOT NULL DEFAULT '{}'::jsonb, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "deletedAt" TIMESTAMP(3));
