CREATE INDEX IF NOT EXISTS "ProductionLine_tenantId_workspaceId_idx" ON "ProductionLine" ("tenantId", "workspaceId");
CREATE INDEX IF NOT EXISTS "ProductionLine_plantId_idx" ON "ProductionLine" ("plantId");

CREATE TABLE IF NOT EXISTS "WorkCenter" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "tenantId" UUID NOT NULL, "workspaceId" UUID, "plantId" UUID, "productionLineId" UUID, "workCenterKey" TEXT NOT NULL, "name" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'available', "workCenterType" TEXT NOT NULL DEFAULT 'cell', "capacityProfile" JSONB NOT NULL DEFAULT '{}'::jsonb, "constraints" JSONB NOT NULL DEFAULT '{}'::jsonb, "metadata" JSONB NOT NULL DEFAULT '{}'::jsonb, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "deletedAt" TIMESTAMP(3));
