CREATE TABLE IF NOT EXISTS "FactoryResource" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "tenantId" UUID NOT NULL, "workspaceId" UUID, "plantId" UUID, "workCenterId" UUID, "resourceKey" TEXT NOT NULL, "name" TEXT NOT NULL, "resourceType" TEXT NOT NULL DEFAULT 'machine', "status" TEXT NOT NULL DEFAULT 'available', "capacityUnits" DECIMAL(18,4) NOT NULL DEFAULT 0, "maintenanceStatus" TEXT NOT NULL DEFAULT 'normal', "metadata" JSONB NOT NULL DEFAULT '{}'::jsonb, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "deletedAt" TIMESTAMP(3));
