CREATE TABLE IF NOT EXISTS "BillOfMaterial" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(), "tenantId" UUID NOT NULL, "workspaceId" UUID, "itemId" UUID, "bomKey" TEXT NOT NULL, "bomNumber" TEXT NOT NULL, "name" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'draft', "version" INTEGER NOT NULL DEFAULT 1, "outputQuantity" DECIMAL(18,4) NOT NULL DEFAULT 1, "effectiveFrom" TIMESTAMP(3), "effectiveTo" TIMESTAMP(3), "metadata" JSONB NOT NULL DEFAULT '{}'::jsonb, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "deletedAt" TIMESTAMP(3));
